/* Spaceflow interaction prototype – static demo, not a production booking service. */
'use strict';
const KEY='spaceflow-prototype-v1';
const TODAY=(()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`})();
const $=(q)=>document.querySelector(q);
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ICONS={table:'会议桌',desk:'单排会议桌',chair:'椅子',screen:'屏幕',door:'门',window:'窗户',board:'白板'};
const SHAPES={table:[190,88],desk:[130,46],chair:[30,32],screen:[90,15],door:[55,9],window:[85,8],board:[82,14]};
const START_ROOMS=[
{id:'r1',name:'青岚',code:'A-1201',building:'总部 A 座',floor:'12F',capacity:12,type:'董事会式',equip:['投屏','视频会议','白板'],area:46,desc:'适合方案评审、管理层会议与跨部门协作。',rule:'instant',repeat:true,color:'#aac1b2'},
{id:'r2',name:'望舒',code:'A-1203',building:'总部 A 座',floor:'12F',capacity:8,type:'U 型',equip:['投屏','白板'],area:32,desc:'适合小型研讨、培训和互动交流。',rule:'instant',repeat:false,color:'#c5c3ad'},
{id:'r3',name:'栖云',code:'A-0802',building:'总部 A 座',floor:'8F',capacity:20,type:'教室式',equip:['投屏','视频会议','音响'],area:72,desc:'适合部门培训、专题汇报与分享会。',rule:'approval',repeat:false,color:'#bec9c1'},
{id:'r4',name:'知微',code:'B-0608',building:'研发 B 座',floor:'6F',capacity:6,type:'圆桌式',equip:['投屏'],area:23,desc:'适合小团队讨论、项目例会和快速决策。',rule:'instant',repeat:true,color:'#e0c6a5'},
{id:'r5',name:'澄观',code:'B-0905',building:'研发 B 座',floor:'9F',capacity:16,type:'董事会式',equip:['投屏','视频会议','音响','白板'],area:58,desc:'适合正式汇报与多方远程协同。',rule:'approval',repeat:true,color:'#b3c3cb'},
{id:'r6',name:'拾光',code:'B-0602',building:'研发 B 座',floor:'6F',capacity:4,type:'洽谈式',equip:['白板'],area:18,desc:'轻量洽谈和短时沟通。',rule:'instant',repeat:false,color:'#c9d0b0'}
];
function preset(type){let a=[{id:'door1',type:'door',x:84,y:300,r:0},{id:'win1',type:'window',x:365,y:56,r:0},{id:'screen1',type:'screen',x:218,y:44,r:0}];const add=(t,x,y,r=0)=>a.push({id:Math.random().toString(36).slice(2,9),type:t,x,y,r});if(type==='教室式'){for(let k=0;k<3;k++){add('desk',110,122+k*68);add('desk',285,122+k*68);}}else if(type==='U 型'){add('desk',140,105);add('desk',305,105);add('desk',115,203,90);add('desk',328,203,90)}else if(type==='圆桌式'||type==='洽谈式'){add('table',180,140);for(let i=0;i<6;i++)add('chair',172+(i%3)*55,110+Math.floor(i/3)*128)}else{add('table',180,139);for(let i=0;i<5;i++){add('chair',180+i*32,95);add('chair',180+i*32,248)}add('chair',140,167,90);add('chair',386,167,90)}a.push({id:'board1',type:'board',x:74,y:70,r:90});return a}
let stored={};try{stored=JSON.parse(localStorage.getItem(KEY)||'{}')}catch(e){}
const state={page:'explore',selectedRoom:'r1',filters:{building:'all',floor:'all',date:TODAY,start:'10:00',end:'11:00',capacity:0,equip:[]},rooms:START_ROOMS.map(x=>({...x})),bookings:[],layouts:{},selection:null,undo:[],zoom:1,...stored};
state.rooms=(state.rooms||START_ROOMS).map(x=>({...x}));state.layouts=state.layouts||{};
for(const r of state.rooms)if(!state.layouts[r.id])state.layouts[r.id]=preset(r.type);
if(!stored.bookings){state.bookings=[{id:'demo1',roomId:'r1',title:'季度项目沟通会',date:TODAY,start:'10:00',end:'11:30',contact:'张同事',phone:'138 0000 1234',hidden:false,status:'confirmed',owner:'其他用户'},{id:'demo2',roomId:'r2',title:'内部评审',date:TODAY,start:'14:00',end:'16:00',contact:'李同事',phone:'138 0000 5678',hidden:true,status:'confirmed',owner:'其他用户'},{id:'demo3',roomId:'r3',title:'团队月度复盘',date:TODAY,start:'13:00',end:'15:00',contact:'王同事',phone:'138 0000 9876',hidden:false,status:'confirmed',owner:'其他用户'},{id:'demo4',roomId:'r5',title:'业务协同',date:TODAY,start:'09:00',end:'10:00',contact:'周同事',phone:'138 0000 1111',hidden:false,status:'confirmed',owner:'其他用户'}]}
function persist(){const obj={rooms:state.rooms,bookings:state.bookings,layouts:state.layouts};try{localStorage.setItem(KEY,JSON.stringify(obj))}catch(e){toast('当前浏览器不能保存数据')}}
function room(id){return state.rooms.find(r=>r.id===id)}
function isOverlap(a,b,c,d){return a<d&&c<b}
function conflicts(roomId,date,start,end,except){return state.bookings.filter(b=>b.roomId===roomId&&b.date===date&&b.id!==except&&['confirmed','pending'].includes(b.status)&&isOverlap(start,end,b.start,b.end))}
function roomAvailable(r){const f=state.filters;return conflicts(r.id,f.date,f.start,f.end).length===0}
function dateHuman(d){return new Date(`${d}T00:00:00`).toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}
function toast(s){const el=$('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2800)}
const label=(s)=>`<span class="eyebrow">${s}</span>`;
function pageHead(kicker,title,sub,tools=''){return `<div class="page-head"><div>${label(kicker)}<h1>${title}</h1><div class="subtext">${sub}</div></div><div class="section-utilities">${tools}</div></div>`}
function iconShape(o,selected=false){const [w,h]=SHAPES[o.type]||[40,30],x=o.x,y=o.y,r=o.r||0;let shape='';if(o.type==='table'){shape=`<rect width="${w}" height="${h}" rx="20" fill="#b3c6b5" stroke="#8cac97" stroke-width="2"/><path d="M20 ${h/2} H${w-20}" stroke="#96b29f" stroke-width="1" opacity=".5"/>`}
if(o.type==='desk'){shape=`<rect width="${w}" height="${h}" rx="5" fill="#b2c6b6" stroke="#8eae97" stroke-width="1.4"/><path d="M${w/2} 1 V${h-1}" stroke="#9db6a4" stroke-dasharray="3 3"/>`}
if(o.type==='chair'){shape=`<rect x="3" y="3" width="${w-6}" height="${h-8}" rx="7" fill="#d6dfcf" stroke="#9bb5a3" stroke-width="1.3"/><path d="M5 ${h-5} h${w-10}" stroke="#8caa96" stroke-width="5" stroke-linecap="round"/>`}
if(o.type==='screen'){shape=`<rect width="${w}" height="${h}" rx="3" fill="#253d37"/><path d="M6 4 H${w-6}" stroke="#7da898" stroke-width="2"/>`}
if(o.type==='board'){shape=`<rect width="${w}" height="${h}" rx="2" fill="#e3e9dd" stroke="#a2b2a3" stroke-width="2"/>`}
if(o.type==='window'){shape=`<rect width="${w}" height="${h}" fill="#95c8c4" rx="2"/><path d="M${w/2} 0 V${h}" stroke="#e3f3ee" stroke-width="2"/>`}
if(o.type==='door'){shape=`<path d="M0 0 H${w}" stroke="#a6a793" stroke-width="4"/><path d="M0 0 A${w} ${w} 0 0 1 ${w} ${w}" fill="none" stroke="#a6a793" stroke-width="1.4" stroke-dasharray="3 3"/>`}
return `<g class="shape" data-id="${esc(o.id)}" transform="translate(${x} ${y}) rotate(${r},${w/2},${h/2})" style="cursor:${selected?'move':'default'}">${shape}${selected?`<rect x="-6" y="-6" width="${w+12}" height="${h+12}" rx="3" fill="none" stroke="#267b5b" stroke-width="2" stroke-dasharray="5 4"/>`:''}</g>`}
function planSvg(r,mode='preview',opts={}){const objects=state.layouts[r.id]||preset(r.type);return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 390" preserveAspectRatio="xMidYMid meet" class="room-svg ${mode==='edit'?'editable':''}" data-room-id="${r.id}" aria-label="${esc(r.name)}会议室布局图"><defs><pattern id="grid-${mode}" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" fill="none" stroke="#dce7db" stroke-width=".6"/></pattern></defs><rect width="600" height="390" rx="5" fill="#f4f7f1"/><rect width="600" height="390" fill="url(#grid-${mode})" opacity="${mode==='edit'?.85:.28}"/><rect x="60" y="26" width="480" height="334" rx="1" fill="#fdfefa" stroke="#b8cab8" stroke-width="9"/><rect x="75" y="39" width="450" height="306" fill="#fbfcf7"/><rect x="78" y="295" width="72" height="14" fill="#fbfcf7"/><text x="81" y="342" fill="#98ac98" font-size="10">ROOM ${esc(r.code)}</text>${objects.map(o=>iconShape(o,mode==='edit'&&state.selection===o.id)).join('')}<text x="527" y="376" fill="#9eafa1" text-anchor="end" font-size="10">布局示意 · 非工程比例</text></svg>`}
function renderExplore(){const f=state.filters;let floors=[...new Set(state.rooms.filter(r=>f.building==='all'||r.building===f.building).map(r=>r.floor))].sort((a,b)=>parseInt(a)-parseInt(b));let availableFloor=floor=>floors.includes(floor);if(f.floor!=='all'&&!availableFloor(f.floor))f.floor='all';let results=state.rooms.filter(r=>(f.building==='all'||r.building===f.building)&&(f.floor==='all'||r.floor===f.floor)&&r.capacity>=Number(f.capacity)&&f.equip.every(x=>r.equip.includes(x)));const buildings=[...new Set(state.rooms.map(r=>r.building))];return `<section class="page">${pageHead('SPACE EXPLORER','找到刚好合适的空间','根据位置、人数、设备和时间，快速找到适合你的会议室。',`<button class="button" data-action="go-schedule">▦ &nbsp; 查看预订日程</button>`)}
<div class="filter-surface"><div class="filter-grid"><div class="field"><label>楼栋</label><select id="f-building"><option value="all">全部楼栋</option>${buildings.map(x=>`<option ${x===f.building?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>楼层</label><select id="f-floor"><option value="all">全部楼层</option>${floors.map(x=>`<option ${x===f.floor?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>使用日期</label><input id="f-date" type="date" value="${esc(f.date)}" /></div><div class="field"><label>开始时间</label><input id="f-start" type="time" value="${esc(f.start)}" /></div><div class="field"><label>结束时间</label><input id="f-end" type="time" value="${esc(f.end)}" /></div><div class="field"><label>容纳人数</label><select id="f-capacity"><option value="0">不限人数</option>${[4,6,8,12,16,20].map(n=>`<option value="${n}" ${Number(f.capacity)===n?'selected':''}>${n} 人以上</option>`).join('')}</select></div></div><div class="filter-row2"><span class="filter-label">设施要求</span>${['投屏','视频会议','白板','音响'].map(x=>`<button class="chip ${f.equip.includes(x)?'on':''}" data-equip="${x}">${f.equip.includes(x)?'✓ ':''}${x}</button>`).join('')}<button class="linklike" id="clearFilters" style="margin-left:auto">重置筛选 ↺</button></div></div>
<div class="overview-bar"><h2>符合条件的会议室 <span class="muted">(${results.length})</span></h2><small>绿色为空闲时段 · 橙色为已占用</small></div>${results.length?`<div class="rooms-grid">${results.map(r=>`<article class="room-card"><div class="room-art">${planSvg(r)}<span class="art-label">${esc(r.type)}</span><span class="art-status ${roomAvailable(r)?'':'busy'}">${roomAvailable(r)?'● 时段空闲':'● 时段冲突'}</span></div><div class="room-info"><div class="room-topline"><h3>${esc(r.name)}会议室</h3><span class="muted" style="font-size:11px">${r.capacity} 人</span></div><div class="room-meta">${esc(r.building)} · ${r.floor} · ${esc(r.code)}</div><div class="amenities">${r.equip.slice(0,3).map(x=>`<span class="amenity">${esc(x)}</span>`).join('')}</div><div class="room-footer"><span class="availability ${roomAvailable(r)?'':'busy'}">${roomAvailable(r)?'✓ 当前筛选时段可预订':'此时段已被占用'}</span><button data-room="${r.id}">查看详情 ↗</button></div></div></article>`).join('')}</div>`:`<div class="empty-box">没有找到符合全部条件的会议室，请放宽筛选条件。</div>`}<div class="footer-caption">演示数据 · 空间容量与布局仅用于产品评审，非真实办公场所</div></section>`}
function renderDetail(){const r=room(state.selectedRoom)||state.rooms[0],bs=state.bookings.filter(b=>b.roomId===r.id&&b.date===state.filters.date&&b.status!=='cancelled').sort((a,b)=>a.start.localeCompare(b.start));return `<section class="page"><button class="back-btn" data-action="back-explore">← 返回空间发现</button>${pageHead('ROOM PROFILE',`${esc(r.name)}会议室`,` ${esc(r.building)} / ${r.floor} / ${esc(r.code)}`,`<button class="button primary" data-book="${r.id}">＋ 预订会议室</button>`)}<div class="detail-layout"><div class="panel"><div class="panel-title"><h2>空间布局</h2><div class="legend"><span><i></i> 设施示意</span><span><i class="orange"></i> 实际尺度以现场为准</span></div></div><div class="detail-hero">${planSvg(r)}</div><div class="divider-line"></div><div class="panel-title"><h2>空间介绍</h2><span class="status-note">当前为管理员配置的最新布局</span></div><p class="subtext" style="line-height:1.9">${esc(r.desc)}</p><div class="amenities" style="margin-top:18px;margin-bottom:0">${r.equip.map(x=>`<span class="amenity">${esc(x)}</span>`).join('')}</div></div><div class="panel"><div class="panel-title"><h2>基础信息</h2><span class="amenity">${esc(r.type)}</span></div>${[['会议室编号',r.code],['可容纳人数',r.capacity+' 人'],['面积',r.area+' ㎡'],['位置',`${r.building} ${r.floor}`],['预订方式',r.rule==='instant'?'直接预订':r.rule==='approval'?'需要审批':'仅管理员预订'],['周期性预订',r.repeat?'已开放':'未开放']].map(x=>`<div class="info-pair"><span>${esc(x[0])}</span><span>${esc(x[1])}</span></div>`).join('')}<div class="divider-line"></div><div class="panel-title"><h2>${dateHuman(state.filters.date)} · 已占用时段</h2></div>${bs.length?`<div class="time-list">${bs.map(b=>`<div class="time-row occupied"><div><b>${b.start} – ${b.end}</b><div class="muted" style="margin-top:7px">${b.hidden?'私人预订 · 详情已隐藏':esc(b.title)}</div></div><span>${b.hidden?'信息隐藏':esc(b.contact)}</span></div>`).join('')}</div>`:`<p class="subtext">该日暂无预订记录。</p>`}<button class="button primary wide" style="margin-top:22px" data-book="${r.id}">预订这个空间 →</button></div></div></section>`}
function renderSchedule(){const d=state.filters.date,hr=Array.from({length:10},(_,i)=>i+8);return `<section class="page">${pageHead('AVAILABILITY CALENDAR','一眼看清空闲时间','横向对比不同会议室的使用情况，点选空闲格快速预订。',`<div class="field"><input aria-label="日程日期" type="date" id="schedule-date" value="${esc(d)}"/></div>`)}<div class="summary-stats"><div class="stat"><small>当前会议室</small><div class="stat-value">${state.rooms.length}</div><span class="stat-accent">跨 2 座楼栋</span></div><div class="stat"><small>当日已确认预订</small><div class="stat-value">${state.bookings.filter(b=>b.date===d&&b.status==='confirmed').length}</div><span class="stat-accent">实时原型数据</span></div><div class="stat"><small>待审批申请</small><div class="stat-value">${state.bookings.filter(b=>b.date===d&&b.status==='pending').length}</div><span class="stat-accent">预订占位演示</span></div></div><div class="schedule-layout"><div class="panel calendar"><div class="calendar-top"><h2>${dateHuman(d)} · 会议室占用矩阵</h2><div class="legend"><span><i></i> 已预订</span><span><i class="orange"></i> 待审批/隐私预订</span></div></div><div class="sched-grid"><div class="sched-head">会议室 / 时段</div>${hr.map(h=>`<div class="sched-head">${String(h).padStart(2,'0')}:00</div>`).join('')}${state.rooms.map(r=>`<div class="sched-name"><b>${esc(r.name)} · ${r.capacity}人</b><small>${esc(r.building)} / ${r.floor}</small></div>${hr.map(h=>{let start=String(h).padStart(2,'0')+':00',end=String(h+1).padStart(2,'0')+':00',bs=conflicts(r.id,d,start,end),b=bs[0];return `<div class="sched-cell" title="${esc(r.name)} ${start} - ${end}" data-cell="${r.id}|${start}">${b?`<span class="sched-event ${b.hidden||b.status==='pending'?'private':''}" title="${b.hidden?'详情隐藏':esc(b.title)}">${b.hidden?'已占用':esc(b.title)}</span>`:''}</div>`}).join('')}`).join('')}</div></div><aside class="panel"><div class="panel-title"><h2>如何使用</h2></div><div class="hint-card">选择日期后，点击日程表中的空白时段，系统将预填会议室与时间。<br/><br/>灰绿块代表已有预订，橙色块表示信息隐藏或待审批申请。</div><div class="divider-line"></div><h3 style="margin-bottom:12px">快捷操作</h3><button class="button wide" data-action="back-explore">返回筛选会议室 ↗</button><div class="helper" style="margin-top:18px">本页为交互原型；正式版需服务器事务与数据库约束，才能保证并发预订不冲突。</div></aside></div></section>`}
function renderMine(){const bs=state.bookings.filter(b=>b.owner==='me').sort((a,b)=>(b.date+b.start).localeCompare(a.date+a.start));return `<section class="page">${pageHead('MY BOOKINGS','我的预订','查看自己提交的预订申请、已确认会议及取消记录。',`<button class="button primary" data-action="back-explore">＋ 创建新预订</button>`)}<div class="panel"><div class="panel-title"><h2>预订记录 (${bs.length})</h2><button class="button small" id="resetData">重置演示数据</button></div><div class="booking-list">${bs.length?bs.map(b=>`<div class="booking-item"><div><h3><span class="booking-badge ${b.status==='pending'?'pending':b.status==='cancelled'?'cancelled':''}">${b.status==='confirmed'?'已确认':b.status==='pending'?'待审批':'已取消'}</span>${esc(b.title)}</h3><p>${esc(room(b.roomId)?.name)}会议室 · ${b.date} · ${b.start}–${b.end}${b.hidden?' · 联系方式已隐藏':''}</p></div><div>${b.status!=='cancelled'?`<button class="button small" data-cancel="${b.id}">取消预订</button>`:''}</div></div>`).join(''):'<div class="empty-box">还没有自己的预订记录。先去选择一个会议室吧。</div>'}</div></div></section>`}
function renderEditor(){const r=room(state.selectedRoom)||state.rooms[0],objects=state.layouts[r.id]||[],obj=objects.find(o=>o.id===state.selection);return `<section class="page">${pageHead('LAYOUT DESIGNER','把真实空间搬到画布上','拖动家具、门窗和设备，配置会议室内部的示意布局。',`<select id="edit-room" class="button">${state.rooms.map(x=>`<option value="${x.id}" ${r.id===x.id?'selected':''}>${esc(x.name)} · ${esc(x.code)}</option>`).join('')}</select><button class="button" id="undoBtn" ${state.undo.length?'':'disabled'}>↶ 撤销</button><button class="button primary" id="saveLayout">✓ 保存布局</button>`)}<div class="editor-grid"><aside class="panel editor-side"><div class="panel-title"><h2>组件库</h2></div><div class="property-hint">点击组件插入画布；选中后可拖动位置。</div><div class="palette-group">家具</div>${[['table','会议长桌','▰'],['desk','单排桌','▬'],['chair','座椅','▢']].map(x=>`<button class="palette-item" data-add="${x[0]}"><span class="palette-symbol">${x[2]}</span>${x[1]}<span style="margin-left:auto">＋</span></button>`).join('')}<div class="palette-group">建筑与设备</div>${[['door','出入口','↷'],['window','窗户','═'],['screen','显示屏','▣'],['board','白板','▤']].map(x=>`<button class="palette-item" data-add="${x[0]}"><span class="palette-symbol">${x[2]}</span>${x[1]}<span style="margin-left:auto">＋</span></button>`).join('')}<div class="palette-group">快速模板</div><button class="button small wide" id="resetTemplate">应用默认布局模板</button></aside><div class="panel" style="padding:12px"><div class="panel-title" style="padding:5px 7px 0"><h2>${esc(r.name)} · 内部布局</h2><span class="status-note">${objects.length} 个元素 · 非比例尺</span></div><div class="editor-stage" id="editorStage">${planSvg(r,'edit')}<div class="canvas-tip">点击选择 / 拖拽移动 · 支持旋转、复制、删除 · 每次保存至本地</div></div><div class="status-note" style="padding:14px 7px 0">提示：门窗位置以示意为准；不实现工程测量和 CAD 对齐。</div></div><aside class="panel editor-side editor-props"><div class="panel-title"><h2>属性面板</h2></div>${obj?`<div class="editor-selected"><b>${esc(ICONS[obj.type])}</b><div class="property-hint">元素 ID · ${esc(obj.id)}</div></div><div class="property-group"><h3>坐标与旋转</h3><div class="mini-fields"><div><label class="mini-label">X</label><input class="smallinput" type="number" id="prop-x" value="${Math.round(obj.x)}" /></div><div><label class="mini-label">Y</label><input class="smallinput" type="number" id="prop-y" value="${Math.round(obj.y)}" /></div></div><div style="margin-top:10px"><label class="mini-label">旋转（度）</label><input class="smallinput" type="number" id="prop-r" value="${obj.r||0}" step="15" /></div><div class="editor-actions"><button class="button small" id="rotateEl">↻ 旋转 90°</button><button class="button small" id="cloneEl">复制</button><button class="button small" id="deleteEl">删除</button></div></div>`:`<p class="property-hint">先点击画布上的元素以查看属性。<br/><br/>本原型可添加桌椅、门、窗、屏幕和白板，可直接编辑 X/Y 坐标及旋转角度。</p>`}<div class="divider-line"></div><h3>布局数据</h3><p class="property-hint" style="margin-top:9px">采用带版本标识的结构化 JSON，未来可实现布局模板版本与审计。</p><button class="button wide" style="margin-top:15px" id="exportLayout">导出布局 JSON ↓</button><button class="button wide" style="margin-top:8px" id="previewLayout">查看用户端效果 ↗</button></aside></div></section>`}
function renderSettings(){return `<section class="page">${pageHead('ROOM POLICIES','每间会议室，独立定义规则','默认全员可见、可预订；不同空间可以采用不同的申请与周期性预订规则。')}<div class="rules-grid">${state.rooms.map(r=>`<article class="rule-card"><div class="rule-head"><div><b>${esc(r.name)}会议室</b><br><small>${esc(r.building)} · ${esc(r.floor)} · ${esc(r.code)}</small></div><span class="amenity">${r.capacity}人</span></div><div class="field"><label>预订生效方式</label><select data-rule="${r.id}"><option value="instant" ${r.rule==='instant'?'selected':''}>直接预订（默认）</option><option value="approval" ${r.rule==='approval'?'selected':''}>管理员审批</option><option value="admin" ${r.rule==='admin'?'selected':''}>仅管理员可预订</option></select></div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:19px"><div style="font-size:11px">允许周期性预订<br><span class="muted" style="font-size:10px">支持按会议室配置</span></div><input aria-label="${esc(r.name)}周期性预订" type="checkbox" class="toggle" data-repeat="${r.id}" ${r.repeat?'checked':''}/></div></article>`).join('')}</div><div class="panel" style="margin-top:18px"><h2>权限和规则设计说明</h2><p class="subtext" style="line-height:2;margin-top:14px">本页仅演示规则配置的交互与状态持久化。用户/部门可见权限、预订权限分离、审批工作流、周期冲突处理、审计日志等尚未实现，不应据此判断为具备生产安全能力。详见仓库文档。</p></div></section>`}
function render(){const pages={explore:renderExplore,detail:renderDetail,schedule:renderSchedule,mine:renderMine,editor:renderEditor,settings:renderSettings};$('#content').innerHTML=(pages[state.page]||renderExplore)();const texts={explore:'空间发现',detail:'会议室详情',schedule:'预订日程',mine:'我的预订',editor:'布局编辑器',settings:'预订规则'};$('#crumb').textContent=texts[state.page];document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===state.page||(state.page==='detail'&&x.dataset.page==='explore')));document.title=`${texts[state.page]} · 间序 Spaceflow`;if(state.page==='editor')bindCanvas()}
function navigate(p){state.page=p;state.selection=null;render();window.scrollTo({top:0,behavior:'instant'})}
function addElement(type){const arr=state.layouts[state.selectedRoom];saveUndo();const item={id:'e'+Math.random().toString(36).slice(2,8),type,x:190+Math.floor(Math.random()*65),y:150+Math.floor(Math.random()*50),r:0};arr.push(item);state.selection=item.id;render()}
function saveUndo(){state.undo.push(JSON.stringify(state.layouts[state.selectedRoom]));if(state.undo.length>30)state.undo.shift()}
function getSelected(){return state.layouts[state.selectedRoom]?.find(o=>o.id===state.selection)}
function bindCanvas(){const svg=$('#editorStage svg');if(!svg)return;let drag=null;const toPoint=(ev)=>{const p=svg.createSVGPoint();p.x=ev.clientX;p.y=ev.clientY;const inverse=svg.getScreenCTM()?.inverse();return inverse?p.matrixTransform(inverse):{x:0,y:0}};svg.addEventListener('pointerdown',(ev)=>{const target=ev.target.closest('.shape');if(!target){state.selection=null;render();return}const id=target.dataset.id,o=state.layouts[state.selectedRoom].find(x=>x.id===id);if(!o)return;const pt=toPoint(ev);state.selection=id;drag={id,startX:o.x,startY:o.y,x:pt.x,y:pt.y,moved:false};svg.setPointerCapture(ev.pointerId);svg.querySelectorAll('.shape').forEach(el=>{const outline=el.querySelector('[stroke-dasharray="5 4"]');if(outline)outline.remove()});target.insertAdjacentHTML('beforeend',`<rect x="-6" y="-6" width="${(SHAPES[o.type]||[40,30])[0]+12}" height="${(SHAPES[o.type]||[40,30])[1]+12}" rx="3" fill="none" stroke="#267b5b" stroke-width="2" stroke-dasharray="5 4"/>`) });svg.addEventListener('pointermove',(ev)=>{if(!drag)return;const obj=getSelected();if(!obj)return;const pt=toPoint(ev);if(!drag.moved&&Math.hypot(pt.x-drag.x,pt.y-drag.y)>2){saveUndo();drag.moved=true}if(drag.moved){const w=SHAPES[obj.type][0],h=SHAPES[obj.type][1];obj.x=Math.max(65,Math.min(530-w,Math.round(drag.startX+pt.x-drag.x)));obj.y=Math.max(32,Math.min(345-h,Math.round(drag.startY+pt.y-drag.y)));const el=svg.querySelector(`.shape[data-id="${obj.id}"]`);if(el)el.setAttribute('transform',`translate(${obj.x} ${obj.y}) rotate(${obj.r||0},${w/2},${h/2})`)}});const finish=()=>{if(!drag)return;const moved=drag.moved;drag=null;if(moved)persist();render()};svg.addEventListener('pointerup',finish);svg.addEventListener('pointercancel',finish)}
function openBooking(id,start=null){const r=room(id);if(!r)return;$('#modal').classList.add('open');$('#modal').setAttribute('aria-hidden','false');const first=start||state.filters.start, end=start?`${String(Math.min(23,Number(start.slice(0,2))+1)).padStart(2,'0')}:00`:state.filters.end;$('#modalBody').innerHTML=`<form id="bookingForm"><div class="form-grid"><div class="field full-row"><label>会议室</label><input value="${esc(r.name)}会议室 · ${esc(r.building)} ${r.floor}" disabled/></div><div class="field full-row"><label>会议主题 *</label><input name="title" maxlength="70" required placeholder="例如：产品方案评审会"/></div><div class="field full-row"><label>使用日期 *</label><input type="date" name="date" value="${esc(state.filters.date)}" min="${TODAY}" required/></div><div class="field"><label>开始时间 *</label><input type="time" name="start" value="${first}" required/></div><div class="field"><label>结束时间 *</label><input type="time" name="end" value="${end}" required/></div><div class="field"><label>联系人 *</label><input name="contact" value="林管理员" maxlength="35" required/></div><div class="field"><label>联系方式 *</label><input name="phone" value="13800001234" maxlength="50" required/></div><label class="checkbox-row full-row"><input type="checkbox" name="hidden"/> 隐藏会议主题、联系人和联系方式</label><div class="full-row alert" id="bookingError" hidden></div></div><div class="form-foot"><button class="button" type="button" id="cancelModal">取消</button><button class="button primary" type="submit">${r.rule==='approval'?'提交审批申请':'确认预订'} →</button></div><p class="helper">演示逻辑仅存本机浏览器；正式版以服务器权限与时间冲突校验为准。</p></form>`;$('#bookingForm').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);const date=data.get('date'),s=data.get('start'),en=data.get('end');const err=$('#bookingError');const fail=msg=>{err.hidden=false;err.textContent=msg};if(s>=en)return fail('结束时间必须晚于开始时间。');if(date<TODAY)return fail('不能预订过去的日期。');if(r.rule==='admin')return fail('该会议室仅管理员可代订；演示不包含权限提升。');if(conflicts(r.id,date,s,en).length)return fail('该时间段已被预订或有待审批占位，请调整时间。');state.bookings.push({id:'b'+Date.now(),roomId:id,title:String(data.get('title')).trim(),date,start:s,end:en,contact:String(data.get('contact')).trim(),phone:String(data.get('phone')).trim(),hidden:!!data.get('hidden'),status:r.rule==='approval'?'pending':'confirmed',owner:'me'});persist();closeModal();navigate('mine');toast(r.rule==='approval'?'审批申请已记录（演示）':'预订成功（演示）')});$('#cancelModal').onclick=closeModal;setTimeout(()=>$('#bookingForm input[name="title"]')?.focus(),0)}
function closeModal(){$('#modal').classList.remove('open');$('#modal').setAttribute('aria-hidden','true')}
document.body.addEventListener('click',e=>{const node=e.target.closest('button');if(!node)return;if(node.dataset.page){navigate(node.dataset.page);return}if(node.dataset.room){state.selectedRoom=node.dataset.room;navigate('detail');return}if(node.dataset.book){openBooking(node.dataset.book);return}if(node.dataset.equip){const x=node.dataset.equip,arr=state.filters.equip;state.filters.equip=arr.includes(x)?arr.filter(v=>v!==x):[...arr,x];render();return}if(node.dataset.add){addElement(node.dataset.add);return}if(node.dataset.cell){const [id,start]=node.dataset.cell.split('|');if(conflicts(id,state.filters.date,start,`${String(Number(start.slice(0,2))+1).padStart(2,'0')}:00`).length){state.selectedRoom=id;navigate('detail')}else openBooking(id,start);return}if(node.dataset.cancel){if(confirm('确定取消这条预订吗？')){const b=state.bookings.find(x=>x.id===node.dataset.cancel);if(b&&b.owner==='me'){b.status='cancelled';persist();render();toast('预订已取消（演示）')}}return}switch(node.id){case 'clearFilters':state.filters={building:'all',floor:'all',date:TODAY,start:'10:00',end:'11:00',capacity:0,equip:[]};render();break;case 'closeModal':closeModal();break;case 'saveLayout':persist();toast('布局已保存到本机浏览器');break;case 'undoBtn':if(state.undo.length){state.layouts[state.selectedRoom]=JSON.parse(state.undo.pop());state.selection=null;render()}break;case 'resetTemplate':if(confirm('将覆盖此会议室当前布局，是否继续？')){saveUndo();state.layouts[state.selectedRoom]=preset(room(state.selectedRoom).type);state.selection=null;render()}break;case 'deleteEl':if(getSelected()){saveUndo();state.layouts[state.selectedRoom]=state.layouts[state.selectedRoom].filter(x=>x.id!==state.selection);state.selection=null;render()}break;case 'rotateEl':if(getSelected()){saveUndo();getSelected().r=((getSelected().r||0)+90)%360;render()}break;case 'cloneEl':if(getSelected()){const old=getSelected();saveUndo();const o={...old,id:'e'+Math.random().toString(36).slice(2,8),x:old.x+24,y:old.y+24};state.layouts[state.selectedRoom].push(o);state.selection=o.id;render()}break;case 'exportLayout':{const r=room(state.selectedRoom),payload={schemaVersion:1,roomId:r.id,coordinateSystem:{width:600,height:390},elements:state.layouts[r.id]};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`spaceflow-layout-${r.id}.json`;a.click();URL.revokeObjectURL(url);break}case 'previewLayout':navigate('detail');break;case 'resetData':if(confirm('清空自己的预订、恢复所有原始布局和设置？')){localStorage.removeItem(KEY);location.reload()}break;case 'infoBtn':toast('间序 · 产品原型。所有预订和布局编辑都为本地演示。');break;default:if(node.dataset.action==='go-schedule')navigate('schedule');if(node.dataset.action==='back-explore')navigate('explore')}});
document.body.addEventListener('change',e=>{const t=e.target;switch(t.id){case 'f-building':state.filters.building=t.value;state.filters.floor='all';render();break;case 'f-floor':state.filters.floor=t.value;render();break;case 'f-date':case 'schedule-date':state.filters.date=t.value;render();break;case 'f-start':state.filters.start=t.value;if(state.filters.start>=state.filters.end){state.filters.end=`${String(Math.min(23,Number(t.value.slice(0,2))+1)).padStart(2,'0')}:00`}render();break;case 'f-end':state.filters.end=t.value;render();break;case 'f-capacity':state.filters.capacity=Number(t.value);render();break;case 'edit-room':state.selectedRoom=t.value;state.selection=null;state.undo=[];render();break;case 'prop-x':case 'prop-y':case 'prop-r':{const obj=getSelected();if(obj){saveUndo();const key={'prop-x':'x','prop-y':'y','prop-r':'r'}[t.id];obj[key]=Number(t.value)||0;render()}break}}if(t.dataset.rule){const r=room(t.dataset.rule);r.rule=t.value;persist();toast('已更新预订方式（演示）')}if(t.dataset.repeat){room(t.dataset.repeat).repeat=t.checked;persist();toast('已更新周期性预订开关（演示）')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(state.page==='editor'&&state.selection&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){if(e.key==='Delete'||e.key==='Backspace'){$('#deleteEl')?.click()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();$('#undoBtn')?.click()}}});
$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});$('#closeModal').onclick=closeModal;
$('#todayText').textContent=new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'});render();
